{"hypotheses": [
{
"name": "Consumption_Frictions", 
"mechanism": "Variations in consumption patterns due to cyclical factors, consumer sentiment, and market liquidity conditions affect firms differently based on their customer base. Firms with more stable customer bases would perform better in uncertain conditions.", 
"expression": {
    "terms": [
        {"weight": 1.0, "primitive": "CustomerMomentum"},
        {"weight": -0.5, "primitive": "IndMom"},
        {"weight": -0.5, "primitive": "Herf"}
    ], 
    "regime": "VIX_ABOVE_TRAILING_MEDIAN", 
    "vol_target": true
}, 
"auxiliary_predictions": [
    {"type": "regime_interaction", "regime": "VIX_BELOW_TRAILING_MEDIAN", "direction": "lower"}, 
    {"type": "size_segment", "segment": "mega", "direction": "stronger"},
    {"type": "correlation", "primitive": "Mom12m", "bound": "below", "threshold": 0.3}
], 
"expected_annualized_sharpe": 0.6, 
"expected_decay_half_life_months": 24
},
{
"name": "LiquidityRisk_Differential", 
"mechanism": "Firms with higher liquidity risk are likely to have higher expected returns - a risk premium. In periods of high market volatility, this liquidity risk is likely to be exacerbated, leading to higher expected returns.", 
"expression": {
    "terms": [
        {"weight": 1.0, "primitive": "Illiquidity"},
        {"weight": -0.5, "primitive": "BetaTailRisk"}
    ], 
    "regime": "VIX_ABOVE_TRAILING_MEDIAN", 
    "vol_target": false
}, 
"auxiliary_predictions": [
    {"type": "regime_interaction", "regime": "VIX_BELOW_TRAILING_MEDIAN", "direction": "lower"}, 
    {"type": "size_segment", "segment": "small", "direction": "stronger"},
    {"type": "correlation", "primitive": "Beta", "bound": "above", "threshold": 0.3}
], 
"expected_annualized_sharpe": 0.7, 
"expected_decay_half_life_months": 36
},
{
"name": "Quality_Innovation_Spread", 
"mechanism": "High quality companies with innovative capabilities outperform their lower quality peers in the long-run, especially in up-market conditions.", 
"expression": {
    "terms": [
        {"weight": 1.0, "primitive": "PS"},
        {"weight": -1.0, "primitive": "PatentsRD"}
    ], 
    "regime": "MKT_TRAILING_12M_UP", 
    "vol_target": true
}, 
"auxiliary_predictions": [
    {"type": "regime_interaction", "regime": "MKT_TRAILING_12M_DOWN", "direction": "lower"}, 
    {"type": "size_segment", "segment": "mega", "direction": "stronger"},
    {"type": "international", "region": "developed_ex_us", "direction": "same_sign"}
], 
"expected_annualized_sharpe": 0.8, 
"expected_decay_half_life_months": null
},
{
"name": "Investment_Age_Spread", 
"mechanism": "Firms with higher recent investment but older age will have better performance as the newer investments should start yielding returns while the firm benefits from the stability of its age.", 
"expression": {
    "terms": [
        {"weight": 1.0, "primitive": "Investment"},
        {"weight": 0.5, "primitive": "FirmAge"}
    ], 
    "regime": null, 
    "vol_target": false
}, 
"auxiliary_predictions": [
    {"type": "size_segment", "segment": "large", "direction": "stronger"},
    {"type": "international", "region": "emerging", "direction": "same_sign"},
    {"type": "subperiod_consistency"}
], 
"expected_annualized_sharpe": 0.6, 
"expected_decay_half_life_months": 48
},
{
"name": "Fiscal_Drag", 
"mechanism": "Firms with higher tax burden and lower external financing will underperform, especially in down-market conditions as these firms face higher cost of capital and fiscal drag.", 
"expression": {
    "terms": [
        {"weight": -1.0, "primitive": "Tax"},
        {"weight": 0.5, "primitive": "XFIN"}
    ], 
    "regime": "MKT_TRAILING_12M_DOWN", 
    "vol_target": false
}, 
"auxiliary_predictions": [
    {"type": "regime_interaction", "regime": "MKT_TRAILING_12M_UP", "direction": "lower"}, 
    {"type": "size_segment", "segment": "micro", "direction": "stronger"},
    {"type": "correlation", "primitive": "Beta", "bound": "above", "threshold": 0.3}
], 
"expected_annualized_sharpe": 0.5, 
"expected_decay_half_life_months": 60
},
{
"name": "Market_Sentiment_Differential", 
"mechanism": "In periods of low market volatility, firms with higher analyst optimism and higher trading volume will outperform due to positive market sentiment.", 
"expression": {
    "terms": [
        {"weight": 1.0, "primitive": "AOP"},
        {"weight": 0.5, "primitive": "DolVol"}
    ], 
    "regime": "VIX_BELOW_TRAILING_MEDIAN", 
    "vol_target": true
}, 
"auxiliary_predictions": [
    {"type": "regime_interaction", "regime": "VIX_ABOVE_TRAILING_MEDIAN", "direction": "lower"}, 
    {"type": "size_segment", "segment": "large", "direction": "stronger"},
    {"type": "international", "region": "developed_ex_us", "direction": "same_sign"}
], 
"expected_annualized_sharpe": 0.7, 
"expected_decay_half_life_months": null
},
{
"name": "Growth_Leverage_Differential", 
"mechanism": "Older firms with higher asset growth and lower leverage will outperform their peers due to lower financial distress risk and higher operational efficiency.", 
"expression": {
    "terms": [
        {"weight": 1.0, "primitive": "AssetGrowth"},
        {"weight": -0.5, "primitive": "Leverage"},
        {"weight": 0.5, "primitive": "FirmAge"}
    ], 
    "regime": null, 
    "vol_target": false
}, 
"auxiliary_predictions": [
    {"type": "size_segment", "segment": "large", "direction": "stronger"},
    {"type": "international", "region": "emerging", "direction": "same_sign"},
    {"type": "subperiod_consistency"}
], 
"expected_annualized_sharpe": 0.65, 
"expected_decay_half_life_months": 36
},
{
"name": "Credit_Risk_Growth_Differential", 
"mechanism": "In periods of high market volatility, firms with lower credit rating downgrades and higher asset growth will outperform their peers due to lower credit risk and higher investment efficiency.", 
"expression": {
    "terms": [
        {"weight": -1.0, "primitive": "CredRatDG"},
        {"weight": 1.0, "primitive": "AssetGrowth"}
    ], 
    "regime": "VIX_ABOVE_TRAILING_MEDIAN", 
    "vol_target": true
}, 
"auxiliary_predictions": [
    {"type": "regime_interaction", "regime": "VIX_BELOW_TRAILING_MEDIAN", "direction": "lower"}, 
    {"type": "size_segment", "segment": "mega", "direction": "stronger"},
    {"type": "correlation", "primitive": "BetaLiquidityPS", "bound": "below", "threshold": 0.3}
], 
"expected_annualized_sharpe": 0.7, 
"expected_decay_half_life_months": 48
}
]}
